#!/usr/bin/env bash
# GSZ step130 — Trials → storefront-product mapping. /admin/trials gains a
# "Storefront product" column showing which product(s) each IPTV server is
# linked to (via product_plans.bot_sku), so the mapping is visible and
# self-serve. Read-only derived column — no migration. Safe + idempotent.
set -euo pipefail
GSZ=/opt/gsz; TS=$(date +%Y%m%d-%H%M%S); BK="$GSZ/.bak-step130-$TS"; TMP=$(mktemp -d)
FILES=(routes/adminTrials.js views/admin/trials.ejs)
echo "==> step130: trials → storefront-product mapping"
mkdir -p "$BK"; for f in "${FILES[@]}"; do mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; done
echo "    backup: $BK"
restore(){ echo "!! FAILED — restoring"; for f in "${FILES[@]}"; do cp "$BK/$f" "$GSZ/$f"; done; pm2 restart gsz >/dev/null 2>&1 || true; echo "!! restored."; }
trap 'restore' ERR
echo "" | base64 -d > "$TMP/p.js"
echo "==> applying"; node "$TMP/p.js" "$GSZ"
echo "==> validating"; node --check "$GSZ/routes/adminTrials.js"
node -e "const ejs=require('$GSZ/node_modules/ejs');ejs.compile(require('fs').readFileSync('$GSZ/views/admin/trials.ejs','utf8'),{filename:'$GSZ/views/admin/trials.ejs'});console.log('    ejs ok')"
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz; sleep 2
CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true); [ "$CODE" = "200" ] && echo "    homepage 200: OK" || { echo "    homepage $CODE"; false; }
trap - ERR; rm -rf "$TMP"
echo ""; echo "==> step130 OK ✅  Open /admin/trials — each IPTV server now shows its linked storefront product. Turning a trial On makes it live for that product automatically; servers not sold on the storefront are marked clearly."
